/**
 * =============================================================================
 * STARTUP DATABASE MIGRATIONS
 * =============================================================================
 * Two-stage migration runner that fires on gateway startup.
 *
 * Stage 1 — file-based (KS-30): scans the bundled `migrations/` directory
 * (copied into the image at /app/migrations) and applies every NNN_*.sql
 * file in lex order. Files containing "platform" route to PLATFORM_DATABASE_URL,
 * everything else to DATABASE_URL. Tracked in `_secuura_migrations(filename)`
 * so a re-run is idempotent. This is the same source of truth that
 * `scripts/run-migrations.sh` uses for docker-compose; this stage exists so
 * Azure deploys converge on the same end state without dual-mirroring every
 * new migration into both places.
 *
 * Stage 2 — legacy CORE_MIGRATIONS array (transitional fallback): the
 * pre-KS-30 inline SQL strings still run after stage 1 so any schema bits
 * that only live inline (column-add ALTERs, runtime svc_* tables) keep
 * landing on existing deploys. Each new migration should go into a file
 * under `migrations/` and the matching CORE_MIGRATIONS entry should be
 * removed in the same PR.
 *
 * All statements are idempotent (CREATE TABLE IF NOT EXISTS / DO blocks
 * with existence checks). Runs against: main DB, platform DB, AND all
 * tenant databases. Contains ONLY schema definitions — no seed data.
 * =============================================================================
 */

import * as fs from 'fs';
import * as path from 'path';

const log = (level: string, msg: string, meta?: Record<string, unknown>) => {
  const prefix = level === 'warn' ? '[WARN]' : level === 'info' ? '[INFO]' : '[DEBUG]';
  console.log(`${prefix} [startup-migrations] ${msg}`, meta ? JSON.stringify(meta) : '');
};

// ---------------------------------------------------------------------------
// File-based loader (KS-30)
// ---------------------------------------------------------------------------

/**
 * Locate the bundled migrations directory. The Dockerfile copies
 * `migrations/` from the monorepo root into `/app/migrations` of the image,
 * so when this module runs from `dist/startup-migrations.js` the migrations
 * sit at `../migrations` relative to dist. Locally (ts-node, jest) they're
 * at the same relative path from `src/`. The function also supports an
 * explicit MIGRATIONS_DIR override for test harnesses.
 */
function findMigrationsDir(): string | null {
  const explicit = process.env.MIGRATIONS_DIR;
  if (explicit && fs.existsSync(explicit)) return explicit;

  const candidates = [
    path.resolve(__dirname, '..', 'migrations'),
    path.resolve(__dirname, '..', '..', 'migrations'),
    path.resolve(process.cwd(), 'migrations'),
  ];
  for (const dir of candidates) {
    if (fs.existsSync(dir) && fs.statSync(dir).isDirectory()) return dir;
  }
  return null;
}

interface LoadedMigration {
  filename: string;
  sql: string;
  /** True when the filename hints this migration is for the platform DB */
  isPlatform: boolean;
}

function loadMigrationFiles(dir: string): LoadedMigration[] {
  return fs
    .readdirSync(dir)
    .filter((f) => f.endsWith('.sql'))
    .sort() // lex order — matches scripts/run-migrations.sh
    .map((filename) => ({
      filename,
      sql: fs.readFileSync(path.join(dir, filename), 'utf-8'),
      isPlatform: /platform/i.test(filename),
    }));
}

async function applyFileMigrations(
  pg: any,
  connStr: string,
  dbName: 'main' | 'platform',
  migrations: LoadedMigration[],
): Promise<{ applied: number; failed: number }> {
  const pool = new pg.Pool({ connectionString: connStr, max: 2, connectionTimeoutMillis: 10_000 });
  let applied = 0;
  // KS-950: a per-migration warn was already logged below, but nothing was
  // COUNTED, so the caller's summary read "complete { applied: N }" whether 0
  // or 5 files failed. A migration that errors on boot 1 and succeeds on boot 2
  // was invisible either way. Failures are now returned beside the applied count.
  let failed = 0;
  try {
    // Ensure the tracker table exists in this DB.
    await pool.query(`
      CREATE TABLE IF NOT EXISTS _secuura_migrations (
        filename TEXT PRIMARY KEY,
        applied_at TIMESTAMPTZ DEFAULT NOW()
      )
    `);

    for (const m of migrations) {
      // Route by filename: platform-tagged files only land in the platform
      // DB, everything else only in the main DB.
      if (dbName === 'main' && m.isPlatform) continue;
      if (dbName === 'platform' && !m.isPlatform) continue;

      const existing = await pool.query(
        'SELECT 1 FROM _secuura_migrations WHERE filename = $1 LIMIT 1',
        [m.filename],
      );
      if (existing.rows.length > 0) continue;

      try {
        // pg.query with a multi-statement string runs the whole file in one
        // shot. No params, so multi-statement is allowed (params would
        // restrict to single-statement). DO blocks are single statements
        // even when they contain loops + EXECUTE format(...) calls.
        await pool.query(m.sql);
        await pool.query(
          'INSERT INTO _secuura_migrations (filename) VALUES ($1) ON CONFLICT (filename) DO NOTHING',
          [m.filename],
        );
        applied++;
        log('info', `applied ${m.filename}`, { db: dbName });
      } catch (err: any) {
        // Don't crash the gateway on a single bad migration — log and continue.
        // Genuine drift (e.g. a 002 migration referencing a column that
        // doesn't exist on a hand-touched live schema) shouldn't take the
        // service down at boot; the rest of the migrations still need to
        // try, and ops can re-apply by hand.
        log('warn', `migration ${m.filename} failed`, {
          db: dbName,
          error: err?.message?.substring(0, 200),
        });
        failed++;
      }
    }
  } finally {
    await pool.end();
  }
  return { applied, failed };
}

