        `CREATE UNIQUE INDEX IF NOT EXISTS uq_pdr_hash_tenant ON platform_document_registry(content_hash, tenant_id)`,
        `CREATE TABLE IF NOT EXISTS platform_document_type_templates (
          id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
          name VARCHAR(255) NOT NULL, code VARCHAR(100) UNIQUE NOT NULL,
          description TEXT, category VARCHAR(100), is_active BOOLEAN DEFAULT TRUE,
          creator_verification_level VARCHAR(50) DEFAULT 'basic',
          owner_verification_level VARCHAR(50) DEFAULT 'basic',
          viewer_verification_level VARCHAR(50) DEFAULT 'none',
          verifier_verification_level VARCHAR(50) DEFAULT 'standard',
          require_mfa BOOLEAN DEFAULT FALSE, require_kyc BOOLEAN DEFAULT FALSE,
          require_wallet_signature BOOLEAN DEFAULT FALSE,
          auto_anchor BOOLEAN DEFAULT TRUE, anchor_network VARCHAR(50) DEFAULT 'preprod',
          metadata_schema JSONB DEFAULT '[]',
          created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW()
        )`,
      ];
      const { applied, failed } = await migrateDatabase(pg, platformDbUrl, 'platform', platformMigrations);
      // KS-950: "complete" only when nothing failed (the count itself is #932's).
      log(
        failed > 0 ? 'warn' : 'info',
        failed > 0 ? `Platform DB migrations INCOMPLETE — ${failed} FAILED` : `Platform DB migrations complete`,
        { applied, failed },
      );

      // Seed Secuura Co. and client tenants (idempotent — ON CONFLICT DO NOTHING)
      const pSeedPool = new pg.Pool({ connectionString: platformDbUrl, max: 2, connectionTimeoutMillis: 10000 });
      try {
        await pSeedPool.query(`
          INSERT INTO tenants (id, name, slug, domain, industry, country, status) VALUES
            ('a0000000-0000-4000-8000-000000000099', 'Secuura Co.', 'secuura-co', 'secuura.ai', 'Technology', 'United Kingdom', 'active'),
            ('b1000000-0000-4000-8000-000000000001', 'Oxford University', 'oxford-university', 'oxford-test.invalid', 'Education', 'United Kingdom', 'active'),
            ('b2000000-0000-4000-8000-000000000001', 'BUPA Health UK', 'bupa-health-uk', 'bupa-test.invalid', 'Healthcare', 'United Kingdom', 'active'),
            ('b3000000-0000-4000-8000-000000000001', 'Apex Consulting', 'apex-consulting', 'apex-test.invalid', 'Consulting', 'United Kingdom', 'active'),
            ('b4000000-0000-4000-8000-000000000001', 'Greenfield University', 'greenfield-university', 'greenfield-test.invalid', 'Education', 'United Kingdom', 'active'),
            ('b5000000-0000-4000-8000-000000000001', 'Delta Corp', 'delta-corp', 'delta-corp-test.invalid', 'Technology', 'United Kingdom', 'active')
          ON CONFLICT (slug) DO NOTHING
        `);

        // Ensure all tenants have a tenant_config entry pointing to the shared 'secuura' database.
        // On Azure there is a single DB; per-tenant DBs are not provisioned.
        const dbUrl = process.env.DATABASE_URL || '';
        let sharedDbName = 'secuura';
        try { sharedDbName = new URL(dbUrl).pathname.replace(/^\//, '') || 'secuura'; } catch {}
        const sharedDbHost = (() => { try { return new URL(dbUrl).hostname; } catch { return 'postgres'; } })();
        const sharedDbPort = (() => { try { return parseInt(new URL(dbUrl).port || '5432'); } catch { return 5432; } })();

        const tenantIds = [
          '00000000-0000-4000-8000-000000000001',  // default
          'a0000000-0000-4000-8000-000000000001',  // default (alt ID from Docker seed)
          'a0000000-0000-4000-8000-000000000099',  // secuura-co
          'b1000000-0000-4000-8000-000000000001',  // oxford
          'b2000000-0000-4000-8000-000000000001',  // bupa
          'b3000000-0000-4000-8000-000000000001',  // apex
          'b4000000-0000-4000-8000-000000000001',  // greenfield
          'b5000000-0000-4000-8000-000000000001',  // delta
        ];
        for (const tid of tenantIds) {
          try {
            await pSeedPool.query(
              `INSERT INTO tenant_config (tenant_id, db_name, db_host, db_port, token_location_type)
               VALUES ($1, $2, $3, $4, 'manual')
               ON CONFLICT (tenant_id) DO UPDATE SET db_name = $2, db_host = $3, db_port = $4`,
              [tid, sharedDbName, sharedDbHost, sharedDbPort]
            );
          } catch {}
        }

        log('info', 'Platform tenant seed complete (Secuura Co. + 5 client tenants + config)');
      } catch (seedErr: any) {
        log('debug', 'Platform tenant seed skipped', { error: seedErr?.message?.substring(0, 80) });
      } finally {
        await pSeedPool.end();
      }
    } catch (err: any) {
      log('warn', 'Platform DB migrations failed', { error: err?.message });
    }

    // 3. Migrate ALL tenant databases
    if (process.env.MULTI_TENANCY_ENABLED === 'true') {
      try {
        const pPool = new pg.Pool({ connectionString: platformDbUrl, max: 2 });
        const result = await pPool.query(
          `SELECT t.id, t.slug, tc.db_name, tc.db_host, tc.db_port
           FROM tenants t LEFT JOIN tenant_config tc ON t.id = tc.tenant_id
           WHERE t.status = 'active' AND tc.db_name IS NOT NULL`
        );
        await pPool.end();

        // Parse the main DB URL to get credentials
        const url = new URL(dbUrl);
        const baseUser = url.username;
        const basePass = url.password;
        const baseHost = url.hostname;
        const basePort = url.port || '5432';

        let migrated = 0;
        let failedTenants = 0;
        let skipped = 0;

        for (const tenant of result.rows) {
          const tenantDbName = tenant.db_name;
          const tenantHost = tenant.db_host || baseHost;
          const tenantPort = tenant.db_port || basePort;
          const tenantConnStr = `postgresql://${baseUser}:${basePass}@${tenantHost}:${tenantPort}/${tenantDbName}?sslmode=require`;

          try {
            const outcome = await migrateDatabase(pg, tenantConnStr, tenantDbName, CORE_MIGRATIONS);
            // KS-1062 (F-928-4): migrateDatabase never throws, so incrementing
            // `migrated` on return counted every tenant — including one whose
            // database does not exist, where the connection failure surfaces as
            // every statement failing inside it. Only a clean run counts.
            if (outcome.failed > 0) {
              failedTenants++;
              log('warn', `Tenant ${tenant.slug} migrations FAILED`, {
                db: tenantDbName,
                applied: outcome.applied,
                failed: outcome.failed,
                error: outcome.firstError,
              });
            } else {
              migrated++;
            }
          } catch (err: any) {
            log('debug', `Tenant ${tenant.slug} migration skipped`, { error: err?.message?.substring(0, 60) });
            skipped++;
          }
        }

        // KS-950: #932 made a failed tenant countable; "complete" is still
        // reserved for a run in which no tenant failed.
        log(
          failedTenants > 0 ? 'warn' : 'info',
          failedTenants > 0
            ? `Tenant DB migrations INCOMPLETE — ${failedTenants} tenant(s) FAILED`
            : `Tenant DB migrations complete`,
          { migrated, failed: failedTenants, skipped, total: result.rows.length },
        );
      } catch (err: any) {
        log('warn', 'Tenant DB migration scan failed', { error: err?.message });
      }
    }
  }

  // KS-109: provision the least-privilege secuura_app runtime role. Env-guarded
  // (APP_DB_PASSWORD) + idempotent — a no-op until the Key Vault secret is wired
  // into this gateway and the data services' DATABASE_URL is switched to it (see
  // deployment/azure/RLS_ROLE_CUTOVER.md). The migrations above keep running as
  // the admin/owner role, which is correct: DDL needs it, owner is RLS-exempt.
  await provisionAppRole(pg, dbUrl, platformDbUrl);
}

/**
 * KS-1062 (#932) / KS-950 (#973) - what the tenant loop logs when a tenant's migrations fail.
 * The #932 gate (2026-09-13-ks1062-932-c72607d58-tier1-r1, F-1) measured that its tampers left the
 * repository's own suite green; ks1125 later pinned the counter. Three edits still redden nothing:
 * the tenant summary's level forced to info (the gate's T3), its INCOMPLETE headline forced to
 * "complete", and the first-error guard dropped so the LAST error is logged (the gate's T6).
 * runStartupMigrations() is called DIRECTLY with pg redirected, ONLY for the product file, to the
 * fake Pool below (the ks1125 idiom); the control cell proves the redirect before any cell is believed.
 */
import { describe, it, expect, beforeAll, afterAll, vi } from 'vitest';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import Module from 'module';
const PRODUCT = path.join(__dirname, '..', 'startup-migrations.ts');
const SCRATCH = fs.mkdtempSync(path.join(os.tmpdir(), 'ks1062-'));
const FAKE = path.join(SCRATCH, 'fake-pg.cjs');
const EMPTY_MIGRATIONS_DIR = path.join(SCRATCH, 'migrations');
const TENANT_SCAN = 'FROM tenants t LEFT JOIN tenant_config tc';
let TENANTS: Array<Record<string, unknown>> = [];
let lines: string[] = [];
let product: { runStartupMigrations: () => Promise<void> };
const origResolve = (Module as any)._resolveFilename;
function dbOf(connStr: string): string {
  try { return new URL(connStr).pathname.replace(/^\//, ''); } catch { return '?'; }
}
/** No I/O. qa_ghost rejects every statement with one message; qa_two_errors numbers each rejection. */
class FakePool {
  private db: string;
  private refused = 0;
  // KS-1062 N67-1: qa_skip refuses the pool itself; migrateDatabase builds its pool outside its try, so the tenant is SKIPPED.
  constructor(opts: { connectionString: string }) { this.db = dbOf(opts.connectionString); if (this.db === 'qa_skip') throw new Error('qa_skip pool refused'); }
  async query(text: string): Promise<{ rows: unknown[]; rowCount: number }> {
    if (this.db === 'qa_ghost') throw new Error('database "qa_ghost" does not exist');
    if (this.db === 'qa_two_errors') throw new Error('qa statement ' + (++this.refused) + ' refused');
    if (String(text).includes(TENANT_SCAN)) return { rows: TENANTS, rowCount: TENANTS.length };
    return { rows: [], rowCount: 0 };
  }
  async end(): Promise<void> { /* nothing to close */ }
}
const tenant = (slug: string, db: string) => ({ id: 't-' + slug, slug, db_name: db, db_host: null, db_port: null });
async function boot(tenants: Array<Record<string, unknown>>): Promise<void> {
  TENANTS = tenants;
  lines = [];
  const spy = vi.spyOn(console, 'log').mockImplementation((...a: unknown[]) => { lines.push(a.map(String).join(' ')); });
  try { await product.runStartupMigrations(); } finally { spy.mockRestore(); }
}
const summary = () => lines.find((l) => l.includes('[startup-migrations] Tenant DB migrations')) || '';
const metaOf = (line: string) => JSON.parse(line.replace(/^[^{]*/, '') || '{}');
beforeAll(async () => {
  fs.mkdirSync(EMPTY_MIGRATIONS_DIR);
  fs.writeFileSync(FAKE, 'module.exports = globalThis.__KS1062_FAKE_PG;\n');
  (globalThis as any).__KS1062_FAKE_PG = { Pool: FakePool };
  (Module as any)._resolveFilename = function (request: string, parent: any, ...rest: unknown[]) {
    if (request === 'pg' && parent && parent.filename === PRODUCT) return FAKE;
    return origResolve.call(this, request, parent, ...rest);
  };
  vi.stubEnv('DATABASE_URL', 'postgresql://qauser:qapass@qa-main.invalid:5432/qa_main');
  vi.stubEnv('PLATFORM_DATABASE_URL', 'postgresql://qauser:qapass@qa-platform.invalid:5432/qa_platform');
  vi.stubEnv('MULTI_TENANCY_ENABLED', 'true');
  vi.stubEnv('MIGRATIONS_DIR', EMPTY_MIGRATIONS_DIR);
  delete process.env.MIGRATION_DATABASE_URL;
  delete process.env.MIGRATION_PLATFORM_DATABASE_URL;
  delete process.env.APP_DB_PASSWORD;
  product = await import('../startup-migrations');
});
afterAll(() => {
  (Module as any)._resolveFilename = origResolve;
  vi.unstubAllEnvs();
  fs.rmSync(SCRATCH, { recursive: true, force: true });
});
describe('KS-1062: what the tenant loop logs when a tenant fails', () => {
  it('control: pg resolves to the fake, and a clean run is summarised at INFO as complete', async () => {
    expect(Module.createRequire(PRODUCT).resolve('pg')).toBe(FAKE);
    await boot([tenant('qa-one', 'qa_t1'), tenant('qa-two', 'qa_t2')]);
    expect([/^\[INFO\] \[startup-migrations\] Tenant DB migrations complete \{/.test(summary()), metaOf(summary())]).toEqual([true, { migrated: 2, failed: 0, skipped: 0, total: 2 }]);
  });
  it('a failed tenant makes the tenant summary a WARN that says INCOMPLETE, never complete', async () => {
    await boot([tenant('qa-one', 'qa_t1'), tenant('qa-ghost', 'qa_ghost')]);
    expect([/^\[WARN\] \[startup-migrations\] Tenant DB migrations INCOMPLETE . 1 tenant\(s\) FAILED \{/.test(summary()), metaOf(summary())]).toEqual([true, { migrated: 1, failed: 1, skipped: 0, total: 2 }]);
  });
  it('a FAILED tenant line carries the FIRST statement error, not the last', async () => {
    await boot([tenant('qa-two-errors', 'qa_two_errors')]);
    const meta = metaOf(lines.find((l) => l.includes('Tenant qa-two-errors migrations FAILED')) || '');
    expect([meta.failed > 1, meta.error]).toEqual([true, 'qa statement 1 refused']);
  });
  it('RED KS-1062 N67-1: a SKIPPED tenant is counted as skipped, not failed, in the tenant summary', async () => {
    await boot([tenant('qa-one', 'qa_t1'), tenant('qa-ghost', 'qa_ghost'), tenant('qa-skip', 'qa_skip')]);
    expect(metaOf(summary())).toEqual({ migrated: 1, failed: 1, skipped: 1, total: 3 });
  });
  it('RED KS-1062 N79-2: two SKIPPED tenants are both counted as skipped', async () => {
    await boot([tenant('qa-one', 'qa_t1'), tenant('qa-skip-a', 'qa_skip'), tenant('qa-skip-b', 'qa_skip')]);
    expect(metaOf(summary())).toEqual({ migrated: 1, failed: 0, skipped: 2, total: 3 });
  });
  it('RED KS-1062 N79-2: a SKIPPED tenant FIRST does not stop the loop; the migrated and the failed tenant after it are counted', async () => {
    await boot([tenant('qa-skip', 'qa_skip'), tenant('qa-one', 'qa_t1'), tenant('qa-ghost', 'qa_ghost')]);
    expect([/INCOMPLETE . 1 tenant\(s\) FAILED/.test(summary()), metaOf(summary())]).toEqual([true, { migrated: 1, failed: 1, skipped: 1, total: 3 }]);
  });
  it('RED KS-1062 N88-1: when every tenant is skipped, all are counted as skipped and the summary is complete with none migrated', async () => {
    await boot([tenant('qa-skip-a', 'qa_skip'), tenant('qa-skip-b', 'qa_skip')]);
    expect([/^\[INFO\] \[startup-migrations\] Tenant DB migrations complete \{/.test(summary()), metaOf(summary())]).toEqual([true, { migrated: 0, failed: 0, skipped: 2, total: 2 }]);
  });
  it('RED KS-1062 N93-1: a single tenant, skipped, is counted as skipped', async () => {
    await boot([tenant('qa-skip-solo', 'qa_skip')]);
    expect(metaOf(summary())).toEqual({ migrated: 0, failed: 0, skipped: 1, total: 1 });
  });
  it('RED KS-1062 N93-1: when every tenant FAILS, the summary is an INCOMPLETE WARN counting all of them failed', async () => {
    await boot([tenant('qa-ghost-a', 'qa_ghost'), tenant('qa-ghost-b', 'qa_ghost')]);
    expect([summary().startsWith('[WARN] [startup-migrations] Tenant DB migrations INCOMPLETE '), summary().includes(' 2 tenant(s) FAILED {'), metaOf(summary())]).toEqual([true, true, { migrated: 0, failed: 2, skipped: 0, total: 2 }]);
  });
});
